(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.15)*8+Math.cos(y*0.03+t*0.4)*6;
  const w2y = Math.cos(y*0.032+t*0.18)*8+Math.sin(x*0.028-t*0.32)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*90, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*50, 0.085, 1.8, 1.3]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp)*w;
    aS += wave;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*0.5-t*sp*0.4+3.0)*w*0.5;
  }
  const n=8;
  const act=aS/n, inh=iS/n, cor=cS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const weave = Math.sin(sx*0.08+sy*0.06+t*0.7)*Math.cos(sx*0.05-sy*0.09-t*0.5)*0.3;
  const react = act - inh*0.7 + bg*0.3 + spiral + weave + cor*0.4;
  const rd = Math.tanh(react*2.2);
  const lap = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-t*0.8)*Math.cos(sy*0.18+t*0.6)*0.3)*1.5)*0.3;
  const edge = Math.abs(rd)>0.65 ? 1.2 : 1.0;
  const glow = Math.max(0, 1.0-Math.abs(rd)*1.5)*0.15;
  const blend = rd*0.65+lap*0.2+glow*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,85,115],[28,135,128],
    [65,175,145],[160,195,110],[210,185,75],[215,140,65],
    [195,90,70],[155,50,75],[95,28,68],[40,15,55],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(rd*Math.PI)*0.15+glow*0.5;
  const e2 = edge + (Math.abs(rd)>0.85?0.15:0);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*e2)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*e2)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*e2)|0
  ];
}
